export interface PracticeQuestion {
  id: string
  exam_type: 'JAMB' | 'WAEC' | 'NECO' | 'POST_UTME'
  subject: string
  year: number
  question: string
  options: { index: string; value: string }[]
  answer: string
}

function parseOptions(raw: string | { index: string; value: string }[]): { index: string; value: string }[] {
  if (Array.isArray(raw)) return raw
  try { return JSON.parse(raw) } catch { return [] }
}

